// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Mechanism".

Looks like a drill... because it is. They’re constantly digging
tunnels here at the airport. I’m starting to see tunnels in my sleep!

https://www.bahnprojekt-stuttgart-ulm.de/projekt/was-wir-bauen/pfaffensteigtunnel
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2989079/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time-1.6)
#define MN min(R.x,R.y)
float box(vec2 p, vec2 s, float r) {
	p=abs(p)-s+r;
	return length(max(p,.0))+min(.0,max(p.x,p.y))-r;
}
vec3 pattern(vec2 p) {
	// like grids? (+.5 centers the grid)
	p=fract(p+.5)-.5;
	// k for the animation, d for the rectangle, n for the windings (mult. of 4.)
	float k=sin(sin(T)*2.), d=box(p,vec2(.25+.05*k),2e-3), n=4.,
	// background
	bg=fract(length(vec2(atan(p.x,p.y)/6.28318*6.,.01/tan(length(p*.1)))-T+k-5e3)*n);
	// combine background and rectangle
	return exp(vec3(1.8,.5,1.5)+vec3(.5,.2,-.1)*bg)/abs(d*300.);
}
void main() {
	vec2 p=(FC-.5*R)/MN;
	// zoom
	//p*=1.5;
	vec3 col=vec3(0);
	// layers
	for (float i=1.; i<4.; i++) {
		col=mix(col,pattern(p*i),.75);
		// make it more interesting
		p+=.25;
	}
	O=vec4(col,1);
}

